INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 English Grammar, Punctuation and Spelling Vocabulary Practice', 'This quiz focuses on vocabulary related to English grammar, punctuation, and spelling as presented in the 2019 Key Stage 2 national curriculum test. It helps students understand word meanings, suffixes, prefixes, parts of speech, punctuation marks, and sentence structure to improve their language skills.', '[{"id": "q1", "type": "multiSelect", "question": "Which of the following suffixes correctly complete the words: accomplish, forgive, joy, fool?", "hint": "Match each suffix to the word to form a new word.", "explanation": "Suffixes change the meaning or grammatical function of a word. ''ment'' forms ''forgiveness'', ''ful'' forms ''accomplishful'' (not correct, so ''ful'' goes with joy to form joyful), ''ish'' forms ''foolish'', and ''ness'' forms ''joyness'' (not correct, so ''ness'' goes with fool to form foolishness). The correct matches are: accomplish + ment = accomplishment, forgive + ness = forgiveness, joy + ful = joyful, fool + ish = foolish.", "correctAnswer": ["a", "b", "c", "d"], "options": [{"id": "a", "text": "ful"}, {"id": "b", "text": "ment"}, {"id": "c", "text": "ish"}, {"id": "d", "text": "ness"}]}, {"id": "q2", "type": "mcq", "question": "Which sentence must end with a question mark?", "hint": "Look for a sentence that asks something directly.", "explanation": "A question mark is used at the end of a direct question. The sentence ''Did she play tennis on your team last year'' is a direct question and must end with a question mark.", "correctAnswer": "c", "options": [{"id": "a", "text": "The teacher asked them what they were doing"}, {"id": "b", "text": "I wonder what time the next train arrives"}, {"id": "c", "text": "Did she play tennis on your team last year"}, {"id": "d", "text": "He asked if he could use my pen"}]}, {"id": "q3", "type": "fillInBlank", "question": "Insert the correct relative pronoun to complete the sentence: Everyone loved the music ___ was played last night.", "hint": "Relative pronouns include who, which, that.", "explanation": "The relative pronoun ''that'' is used to introduce a clause giving more information about the music. It connects the clause ''was played last night'' to ''music''.", "correctAnswer": "that"}, {"id": "q4", "type": "mcq", "question": "What does the prefix ''multi-'' mean in words like multicultural, multipurpose, and multicoloured?", "hint": "Think about how many or how much the prefix suggests.", "explanation": "The prefix ''multi-'' means ''many'' or ''more than one'', indicating multiple types or purposes.", "correctAnswer": "d", "options": [{"id": "a", "text": "some"}, {"id": "b", "text": "few"}, {"id": "c", "text": "all"}, {"id": "d", "text": "many"}]}, {"id": "q5", "type": "mcq", "question": "Which word is an antonym of ''difficult''?", "hint": "An antonym is a word with the opposite meaning.", "explanation": "The word ''easy'' means not difficult, so it is the antonym of ''difficult''.", "correctAnswer": "b", "options": [{"id": "a", "text": "hard"}, {"id": "b", "text": "easy"}, {"id": "c", "text": "impossible"}, {"id": "d", "text": "challenging"}]}, {"id": "q6", "type": "mcq", "question": "In which sentence is ''lock'' used as a verb?", "hint": "A verb shows an action.", "explanation": "''Lock'' is a verb when it describes the action of securing something, as in ''Make sure you lock the gate before you leave.''", "correctAnswer": "b", "options": [{"id": "a", "text": "Aisha closed the box and fastened the lock."}, {"id": "b", "text": "Make sure you lock the gate before you leave."}, {"id": "c", "text": "I think I need to buy a new bike lock."}, {"id": "d", "text": "The lock can only be opened with this special key."}]}, {"id": "q7", "type": "mcq", "question": "Which sentence is punctuated correctly?", "hint": "Look for correct use of dashes and sentence flow.", "explanation": "The sentence ''I will be running a half marathon \u2013 13 miles \u2013 next week!'' correctly uses dashes to add extra information.", "correctAnswer": "d", "options": [{"id": "a", "text": "I will be running \u2013 a half marathon 13 miles next week!"}, {"id": "b", "text": "I will be \u2013 running a half marathon \u2013 13 miles next week!"}, {"id": "c", "text": "I will be running a half marathon 13 \u2013 miles \u2013 next week!"}, {"id": "d", "text": "I will be running a half marathon \u2013 13 miles \u2013 next week!"}]}, {"id": "q8", "type": "fillInBlank", "question": "Complete the sentence with a word formed from the root word ''music'': Every member of the Jones family was ___, but only Mr Jones was a professional ___.", "hint": "Think of an adjective and a noun related to music.", "explanation": "''Musical'' is an adjective describing someone who has a talent for music, and ''musician'' is a noun for a person who performs music professionally.", "correctAnswer": "musical, musician"}, {"id": "q9", "type": "mcq", "question": "Which sentence uses tense correctly?", "hint": "Check the order and agreement of past and present tense verbs.", "explanation": "The sentence ''We sat and ate our lunch once we had found a sunny picnic spot.'' correctly uses past perfect and simple past tenses in the right order.", "correctAnswer": "a", "options": [{"id": "a", "text": "We sat and ate our lunch once we had found a sunny picnic spot."}, {"id": "b", "text": "Once we find a sunny picnic spot, we sat and ate our lunch."}, {"id": "c", "text": "Once we had found a sunny picnic spot, we sit and eat our lunch."}, {"id": "d", "text": "We sat and eat our lunch once we had found a sunny picnic spot."}]}]', '8b9e97d4-2f6a-4794-b525-3c7f8a20730d', NOW());

INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 Spelling and Vocabulary Practice', 'This quiz focuses on vocabulary and spelling skills appropriate for Key Stage 2 students. It includes fill-in-the-blank, multiple choice, and multi-select questions to help learners understand word meanings, correct spellings, and usage in context.', '[{"id": "q1", "type": "fillInBlank", "question": "The dragon is an imaginary ___.", "hint": "Think of a word that means something made up or not real.", "explanation": "The word ''creature'' fits here as it refers to a living being, and ''imaginary creature'' means a made-up or fictional being.", "correctAnswer": "creature"}, {"id": "q2", "type": "mcq", "question": "Which word best completes the sentence: ''There was ___ food for everyone.''?", "hint": "The word means enough or more than enough.", "explanation": "''Plenty'' means a large or sufficient amount, so it correctly completes the sentence indicating enough food for all.", "correctAnswer": "a", "options": [{"id": "a", "text": "plenty"}, {"id": "b", "text": "little"}, {"id": "c", "text": "scarce"}, {"id": "d", "text": "empty"}]}, {"id": "q3", "type": "fillInBlank", "question": "Playing in the snow made my fingers ___.", "hint": "Think of a word that means feeling very cold.", "explanation": "The word ''numb'' means lacking sensation, often due to cold, so it fits the context of fingers feeling cold after playing in snow.", "correctAnswer": "numb"}, {"id": "q4", "type": "multiSelect", "question": "Select all words that mean ''to give something to someone'' or ''offer''.", "hint": "Think about words related to giving or presenting.", "explanation": "Words like ''gave'' and ''offered'' both mean to present or hand over something to someone.", "correctAnswer": ["a", "b", "e"], "options": [{"id": "a", "text": "gave"}, {"id": "b", "text": "offered"}, {"id": "c", "text": "took"}, {"id": "d", "text": "received"}, {"id": "e", "text": "shared"}]}, {"id": "q5", "type": "mcq", "question": "Which word best fits: ''Do your stretches so you don\u2019t pull a ___.''?", "hint": "This word is a type of injury related to muscles.", "explanation": "''Muscle'' is the correct word because pulling a muscle refers to a common injury caused by overstretching.", "correctAnswer": "b", "options": [{"id": "a", "text": "bone"}, {"id": "b", "text": "muscle"}, {"id": "c", "text": "nerve"}, {"id": "d", "text": "tendon"}]}]', '8b9e97d4-2f6a-4794-b525-3c7f8a20730d', NOW());

INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 English Grammar, Punctuation, and Spelling Vocabulary Practice', 'This quiz focuses on vocabulary related to English grammar, punctuation, and spelling as presented in the 2023 Key Stage 2 national curriculum tests. It helps students understand terms such as exclamation, command, suffix, antonym, formal language, punctuation marks, verb forms, pronouns, conjunctions, and sentence structure.', '[{"id": "q1", "type": "mcq", "question": "Which word best describes a sentence that shows strong feeling or emotion?", "hint": "Think about sentences that end with an exclamation mark.", "explanation": "An exclamation is a sentence that expresses strong emotion or feeling, often ending with an exclamation mark.", "correctAnswer": "a", "options": [{"id": "a", "text": "Exclamation"}, {"id": "b", "text": "Question"}, {"id": "c", "text": "Command"}, {"id": "d", "text": "Statement"}]}, {"id": "q2", "type": "mcq", "question": "Which sentence is a command?", "hint": "Commands tell someone to do something.", "explanation": "A command tells someone to do something directly, often starting with a verb.", "correctAnswer": "c", "options": [{"id": "a", "text": "The relay race will be next."}, {"id": "b", "text": "I hope I don\u2019t drop the baton."}, {"id": "c", "text": "Run as fast as you can."}, {"id": "d", "text": "I know you can win this race."}]}, {"id": "q3", "type": "multiSelect", "question": "Which two words are antonyms?", "hint": "Antonyms are words with opposite meanings.", "explanation": "Antonyms are pairs of words that have opposite meanings, such as proper and improper.", "correctAnswer": ["c"], "options": [{"id": "a", "text": "marine / submarine"}, {"id": "b", "text": "unicycle / bicycle"}, {"id": "c", "text": "proper / improper"}, {"id": "d", "text": "act / interact"}]}, {"id": "q4", "type": "fillInBlank", "question": "Complete the sentence: The word ''social'' can become an adjective by adding the suffix ___.", "hint": "Think about common adjective endings.", "explanation": "Adding the suffix ''-al'' to ''social'' forms the adjective ''social'' itself, but in the test context, suffixes like ''-ish'', ''-al'', ''-ise'', and ''-ship'' are used to form different words.", "correctAnswer": "al"}, {"id": "q5", "type": "mcq", "question": "Which sentence is the most formal?", "hint": "Formal sentences use polite and precise language.", "explanation": "Formal sentences use polite, clear, and precise language, often avoiding contractions and slang.", "correctAnswer": "b", "options": [{"id": "a", "text": "We can\u2019t keep your things here, as there\u2019s no room."}, {"id": "b", "text": "It is essential that you take all your belongings with you."}, {"id": "c", "text": "Please pack up all your stuff before you leave."}, {"id": "d", "text": "It\u2019s time to get all your bits and pieces together."}]}, {"id": "q6", "type": "mcq", "question": "What is the function of a colon in a sentence?", "hint": "Colons often introduce a list or explanation.", "explanation": "A colon is used to introduce a list, explanation, or quotation following an independent clause.", "correctAnswer": "b", "options": [{"id": "a", "text": "To join two independent clauses with a conjunction."}, {"id": "b", "text": "To introduce a list or explanation."}, {"id": "c", "text": "To separate items in a list."}, {"id": "d", "text": "To show possession."}]}, {"id": "q7", "type": "fillInBlank", "question": "Fill in the blank: A word that means the opposite of ''honest'' can be formed by adding the prefix ___.", "hint": "Common prefixes that mean ''not'' include ''un-'', ''in-'', and ''dis-''.", "explanation": "The prefix ''dis-'' is added to ''honest'' to form ''dishonest'', which means not honest.", "correctAnswer": "dis"}, {"id": "q8", "type": "multiSelect", "question": "Which words in the sentence are synonyms? \"Rita was overjoyed when she won the competition \u2013 her mum was delighted too!\"", "hint": "Synonyms are words with similar meanings.", "explanation": "The words ''overjoyed'' and ''delighted'' both express happiness and are synonyms.", "correctAnswer": ["b"], "options": [{"id": "a", "text": "Rita / mum"}, {"id": "b", "text": "overjoyed / delighted"}, {"id": "c", "text": "won / competition"}, {"id": "d", "text": "was / too"}]}, {"id": "q9", "type": "mcq", "question": "Which word is a pronoun in the sentence: \"Maggie and Helena tried to go after school but the museum was closed.\"?", "hint": "Pronouns replace nouns.", "explanation": "Pronouns are words that replace nouns to avoid repetition. In this sentence, ''they'' would be the pronoun replacing ''Maggie and Helena''.", "correctAnswer": "d", "options": [{"id": "a", "text": "Maggie"}, {"id": "b", "text": "Helena"}, {"id": "c", "text": "museum"}, {"id": "d", "text": "none"}]}, {"id": "q10", "type": "mcq", "question": "Which sentence uses the apostrophe correctly for possession?", "hint": "Possessive apostrophes show ownership.", "explanation": "An apostrophe placed before the ''s'' or after the plural ''s'' shows possession, e.g., ''the teachers\u2019 coats'' means coats belonging to the teachers.", "correctAnswer": "b", "options": [{"id": "a", "text": "Let\u2019s hope it warms up soon."}, {"id": "b", "text": "The teachers\u2019 coats were hanging in the staffroom."}, {"id": "c", "text": "The children wear their scarves when it\u2019s cold."}, {"id": "d", "text": "Its a nice day."}]}]', '8b9e97d4-2f6a-4794-b525-3c7f8a20730d', NOW());

